int knap(const vector<int>& w, const vector<int>& v, int W) {
    vector<int> dp(W + 1, 0);
    for (size_t i = 0; i < w.size(); ++i)
        for (int c = w[i]; c <= W; ++c)
            dp[c] = max(dp[c], dp[c - w[i]] + v[i]);
    return dp[W];
}

